const raw = $input.first().json;

// Parser le body correctement — supporte string avec = parasite
let data = raw;
if (raw.body !== undefined) {
  let rawBody = raw.body;
  if (typeof rawBody === 'string') {
    rawBody = rawBody.replace(/^=+/, '').trim();
    try { data = JSON.parse(rawBody); } catch(e) { data = raw; }
  } else if (typeof rawBody === 'object') {
    data = rawBody;
  }
}

const pkg = data.package_json || data.packageJson || null;

if (!pkg) {
  return [{
    json: {
      _error: "YES",
      _error_code: "VALIDATION_ERROR",
      _error_message: "package_json manquant dans le payload",
      task_id: data.task_id || "unknown",
      language: data.language || "javascript",
      queries: []
    }
  }];
}

let parsed;
try {
  parsed = typeof pkg === "string" ? JSON.parse(pkg) : pkg;
} catch (e) {
  return [{
    json: {
      _error: "YES",
      _error_code: "PARSE_ERROR",
      _error_message: "package_json invalide — JSON malformé",
      task_id: data.task_id || "unknown",
      language: data.language || "javascript",
      queries: []
    }
  }];
}

const deps = {
  ...(parsed.dependencies || {}),
  ...(parsed.devDependencies || {})
};

const queries = Object.keys(deps).map(name => ({
  package: { name, ecosystem: "npm" },
  version: deps[name].replace(/[^\d.]/g, "")
}));

return [{
  json: {
    _error: "NO",
    task_id: data.task_id || "unknown",
    language: data.language || "javascript",
    queries
  }
}];

const input = $input.first().json;

// Court-circuit si erreur amont
if (input._error === "YES") {
  return [{
    json: {
      agent: "Agent SCA",
      task_id: input.task_id || "unknown",
      status: "ERROR",
      global_score: 0,
      approved_for_pipeline: false,
      language: input.language || "javascript",
      critical_issues: [],
      warnings: [],
      recommendations: [input._error_message || "Erreur de validation"],
      dimensions: { security: { score: 0 }, quality: { score: 0 } },
      summary: input._error_message || "Erreur de validation",
      timestamp: new Date().toISOString()
    }
  }];
}

const results = input.results || [];
const taskNode = $('Extract & Prepare').first().json;
const _queries = taskNode.queries || [];
let critical = [];
let warnings = [];

// Les resultats OSV querybatch sont dans le MEME ORDRE que les requetes envoyees,
// on peut donc retrouver le paquet et la version reels (querybatch ne renvoie que l id).
for (let i = 0; i < results.length; i++) {
  const r = results[i] || {};
  const q = _queries[i] || {};
  const pkgName = (q.package && q.package.name) || "unknown";
  const pkgVer  = q.version || "";
  const vulns = r.vulns || [];
  for (const v of vulns) {
    const id       = v.id || "UNKNOWN";
    const sevScore = (v.severity && v.severity[0] && v.severity[0].score) || 0;
    const severity = sevScore >= 7 ? "high" : "medium";
    const advisory = "https://osv.dev/vulnerability/" + id;
    const issue = {
      id,
      severity,
      package: pkgName,
      version: pkgVer,
      aliases: (v.aliases || []).join(', ') || id,
      advisory,
      description: id + " dans " + pkgName + "@" + pkgVer,
      impact: severity === "high"
        ? "Exploitation potentielle en production"
        : "Risque a evaluer selon le contexte",
      fix: "Voir " + advisory + " pour la version corrigee de " + pkgName
    };
    if (severity === "high") critical.push(issue);
    else warnings.push(issue);
  }
}

const secScore = Math.max(0, 100 - (critical.length * 30) - (warnings.length * 5));
const qualScore = critical.length > 0 ? 60 : warnings.length > 0 ? 80 : 100;
const globalScore = Math.round((secScore * 0.8) + (qualScore * 0.2));

// WARN au lieu de NEEDSIMPROVEMENT
const status = critical.length > 0 ? "FAIL"
             : warnings.length > 0 ? "WARN"
             : "PASS";

return [{
  json: {
    agent: "Agent SCA",
    _version: "5.1",
    task_id: taskNode.task_id || "unknown",
    status,
    global_score: globalScore,
    approved_for_pipeline: status !== "FAIL",
    language: taskNode.language || "javascript",
    critical_issues: critical,
    warnings,
    recommendations: critical.length > 0
      ? [`Corriger immédiatement ${critical.length} CVE critique(s)`]
      : warnings.length > 0
        ? ["Planifier la mise à jour des dépendances vulnérables"]
        : ["Aucune CVE détectée — dépendances saines"],
    dimensions: {
      security: { score: secScore },
      quality:  { score: qualScore }
    },
    summary: critical.length > 0
      ? `${critical.length} CVE critique(s) dans les dépendances`
      : warnings.length > 0
        ? `${warnings.length} vulnérabilité(s) modérée(s) détectée(s)`
        : "Aucune vulnérabilité dans les dépendances",
    timestamp: new Date().toISOString()
  }
}];
